import React from 'react';
import { useNavigate } from 'react-router-dom';

function Home() {
  const navigate = useNavigate();

  return (
    <div className="card">
      <h2 style={{ marginBottom: '1rem' }}>Welcome to Student Team Management</h2>
      <p style={{ marginBottom: '2rem' }}>
        This application helps you manage your team members efficiently. You can add new members,
        view existing members, and access detailed information about each team member.
      </p>
      <div style={{ display: 'flex', gap: '1rem' }}>
        <button className="btn btn-primary" onClick={() => navigate('/add')}>
          Add New Member
        </button>
        <button className="btn btn-primary" onClick={() => navigate('/members')}>
          View All Members
        </button>
      </div>
    </div>
  );
}

export default Home;
